import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = 0
    my_defects = 0
    for me, op in history:
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    last_me, last_op = history[-1]

    # Detect recent behavior windows
    recent = history[-12:]
    recent_opp_d = 0
    recent_opp_c = 0
    for _, op in recent:
        if op == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
    recent_len = len(recent)

    run_opp_d = 0
    for me, op in reversed(history):
        if op == 'D':
            run_opp_d += 1
        else:
            break

    run_opp_c = 0
    for me, op in reversed(history):
        if op == 'C':
            run_opp_c += 1
        else:
            break

    # Always cooperate against a perfect cooperator, exploit only at the very end.
    if opp_defects == 0:
        if n >= 96:
            return 'D'
        return 'C'

    defect_rate = opp_defects / n

    # Near the end, exploit a mostly cooperative opponent.
    if n >= 94:
        if defect_rate < 0.25 and last_op == 'C':
            return 'D'
        if defect_rate > 0.6:
            return 'D'
        if defect_rate < 0.25:
            return 'C'

    # Chronic defector: against very high defection rates, defect nearly always.
    if defect_rate > 0.75 and recent_opp_c <= 1:
        return 'D'

    # Strong recovery: if we've both been cooperating recently, keep cooperating.
    if recent_opp_d == 0:
        return 'C'

    # Opponent just defected.
    if last_op == 'D':
        # Long defection streak: punish, but allow rare cooperative probe.
        if run_opp_d >= 3:
            if rng.random() < 0.06:
                return 'C'
            return 'D'
        # Single or double recent defection: brief punishment with a chance to forgive.
        if defect_rate < 0.15 and n >= 6:
            # Mostly cooperative opponent with an isolated slip: forgive often.
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        if defect_rate < 0.35:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        # Moderately defective partner
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we defected last round as punishment, strongly prefer to return to cooperation.
    if last_me == 'D':
        if run_opp_c >= 1 and defect_rate < 0.5:
            return 'C'
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    # Both cooperated last round: stay cooperative unless partner is
    # moderately defection-prone and we want occasional exploitation.
    if defect_rate < 0.2:
        return 'C'

    if defect_rate < 0.45:
        # Mostly cooperative; cooperate but probe occasionally.
        if recent_opp_d >= 2 and rng.random() < 0.2:
            return 'D'
        if rng.random() < 0.9:
            return 'C'
        return 'D'

    # Medium-high defection: cooperate only sometimes to probe for recovery.
    if recent_opp_d >= 4:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if rng.random() < 0.7:
        return 'C'
    return 'D'
